"""Week 4 Day 9 bounded tool-evidence course-code tests."""

import hashlib
import json

import pytest

from .tiny_llm_base import (
    AgentLimits,
    ArtifactRef,
    ArtifactStore,
    BoundedEvidenceWorkspace,
    ToolAction,
    ToolPolicy,
    Workspace,
    run_agent,
)


def _payload(observation: str, prefix: str) -> dict:
    assert observation.startswith(prefix)
    return json.loads(observation.removeprefix(prefix))


def _workspace(tmp_path, content: str, **limits):
    workspace_root = tmp_path / "workspace"
    artifact_root = tmp_path / "artifacts"
    workspace_root.mkdir()
    artifact_root.mkdir()
    (workspace_root / "build.log").write_text(content, encoding="utf-8")
    workspace = Workspace(ToolPolicy(workspace_root, max_file_bytes=32_000))
    artifacts = ArtifactStore(artifact_root)
    return BoundedEvidenceWorkspace(workspace, artifacts, **limits), artifacts


def test_task_1_artifact_store_preserves_exact_bytes_and_identity(tmp_path):
    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    store = ArtifactStore(artifact_root)
    result = "α\n" + "build output\n" * 40
    data = result.encode("utf-8")

    record = store.put(result)

    digest = hashlib.sha256(data).hexdigest()
    assert record == ArtifactRef(f"artifact-{digest}", len(data), digest)
    assert (artifact_root / record.artifact_id).read_bytes() == data
    assert store.read_range(record.artifact_id, 2, 17) == data[2:17]
    assert store.put(result) == record
    with pytest.raises(ValueError, match="artifact id"):
        ArtifactRef("artifact-UPPER", len(data), digest)
    with pytest.raises(ValueError, match="byte count"):
        ArtifactRef(record.artifact_id, -1, digest)
    with pytest.raises(ValueError, match="digest"):
        ArtifactRef(record.artifact_id, len(data), "not-a-digest")
    other_digest = hashlib.sha256(b"other").hexdigest()
    with pytest.raises(ValueError, match="must match"):
        ArtifactRef(record.artifact_id, len(data), other_digest)


def test_task_2_oversized_result_becomes_bounded_verifiable_observation(tmp_path):
    content = "HEAD----" + "x" * 3_000 + "----TAIL"
    bounded, artifacts = _workspace(
        tmp_path,
        content,
        max_inline_bytes=512,
        preview_bytes=8,
        max_range_bytes=24,
    )

    observation = bounded.execute(ToolAction("read_file", {"path": "build.log"}))
    payload = _payload(observation, "Tool result externalized:\n")

    data = content.encode()
    digest = hashlib.sha256(data).hexdigest()
    artifact_id = f"artifact-{digest}"
    assert payload == {
        "artifact_id": artifact_id,
        "byte_count": len(data),
        "head_preview": "HEAD----",
        "head_range": [0, 8],
        "omitted_range": [8, len(data) - 8],
        "range_request": {
            "path": artifacts.range_path(artifact_id, 0, 24),
            "tool": "read_file",
        },
        "sha256": digest,
        "tail_preview": "----TAIL",
        "tail_range": [len(data) - 8, len(data)],
    }
    assert len(observation.encode()) <= bounded.max_inline_bytes
    assert len(observation) < len(content)
    assert (artifacts.root / artifact_id).read_bytes() == data

    unicode_content = "αβγ" + "x" * 1_000 + "δεζ"
    unicode_root = tmp_path / "unicode"
    unicode_root.mkdir()
    unicode_artifacts = tmp_path / "unicode-artifacts"
    unicode_artifacts.mkdir()
    (unicode_root / "build.log").write_text(unicode_content, encoding="utf-8")
    unicode = BoundedEvidenceWorkspace(
        Workspace(ToolPolicy(unicode_root, max_file_bytes=32_000)),
        ArtifactStore(unicode_artifacts),
        max_inline_bytes=512,
        preview_bytes=5,
        max_range_bytes=24,
    )
    rendered = unicode.execute(ToolAction("read_file", {"path": "build.log"}))
    unicode_payload = _payload(rendered, "Tool result externalized:\n")
    assert "�" not in unicode_payload["head_preview"]
    assert "�" not in unicode_payload["tail_preview"]
    assert len(rendered.encode()) <= unicode.max_inline_bytes


def test_task_2_externalization_uses_utf8_bytes_at_the_exact_inline_boundary(
    tmp_path,
):
    inline, _ = _workspace(tmp_path, "a" * 512)
    assert inline.execute(ToolAction("read_file", {"path": "build.log"})) == "a" * 512

    multibyte_root = tmp_path / "multibyte"
    multibyte_root.mkdir()
    multibyte_artifacts = tmp_path / "multibyte-artifacts"
    multibyte_artifacts.mkdir()
    content = "é" * 512
    (multibyte_root / "build.log").write_text(content, encoding="utf-8")
    multibyte = BoundedEvidenceWorkspace(
        Workspace(ToolPolicy(multibyte_root, max_file_bytes=32_000)),
        ArtifactStore(multibyte_artifacts),
    )

    result = multibyte.execute(ToolAction("read_file", {"path": "build.log"}))
    payload = _payload(result, "Tool result externalized:\n")
    assert payload["byte_count"] == len(content.encode("utf-8")) == 1_024


