def test_task_5_existing_agent_loop_retrieves_evidence_then_continues(tmp_path):
    diagnostic = "ERROR code=E42 dependency mismatch"
    content = "head\n" + "x" * 500 + diagnostic + "\n" + "y" * 500 + "\ntail"
    bounded, artifacts = _workspace(
        tmp_path,
        content,
        max_inline_bytes=512,
        preview_bytes=8,
        max_range_bytes=64,
    )
    digest = hashlib.sha256(content.encode()).hexdigest()
    artifact_id = f"artifact-{digest}"
    start = content.encode().index(diagnostic.encode())
    end = start + len(diagnostic.encode())
    responses = iter(
        (
            '{"tool":"read_file","path":"build.log"}',
            json.dumps(
                {
                    "tool": "read_file",
                    "path": artifacts.range_path(artifact_id, start, end),
                },
                separators=(",", ":"),
            ),
            '{"final":"The requested range contains diagnostic E42."}',
        )
    )

    run = run_agent(
        "Inspect the large build log and retrieve the diagnostic range.",
        lambda _messages: next(responses),
        bounded,
        AgentLimits(max_steps=3),
    )

    assert run.completed and run.final == "The requested range contains diagnostic E42."
    assert len(run.events) == 3
    assert diagnostic not in run.events[0].result
    range_payload = _payload(run.events[1].result, "Artifact range:\n")
    assert range_payload["artifact_id"] == artifact_id
    assert range_payload["start"] == start and range_payload["end"] == end
    assert range_payload["data"] == diagnostic
    assert (artifacts.root / artifact_id).read_bytes() == content.encode()


def test_task_6_small_and_error_results_remain_inline_and_state_is_delegated(
    tmp_path, monkeypatch
):
    bounded, artifacts = _workspace(
        tmp_path,
        "small result\n",
        max_inline_bytes=512,
        preview_bytes=8,
        max_range_bytes=16,
    )

    result = bounded.execute(ToolAction("read_file", {"path": "build.log"}))

    assert result == "small result\n"
    assert bounded.policy is bounded.workspace.policy
    assert bounded.available_tools == bounded.workspace.available_tools
    assert bounded.modified_files == ()
    assert list(artifacts.root.iterdir()) == []

    long_error = "error: " + "x" * 1_000
    monkeypatch.setattr(bounded.workspace, "execute", lambda *_args: long_error)
    assert bounded.execute(ToolAction("read_file", {"path": "missing"})) == long_error
    assert list(artifacts.root.iterdir()) == []

    with pytest.raises(ValueError, match="at least 512"):
        BoundedEvidenceWorkspace(bounded.workspace, artifacts, max_inline_bytes=511)
    with pytest.raises(ValueError, match="must not exceed"):
        BoundedEvidenceWorkspace(
            bounded.workspace,
            artifacts,
            max_inline_bytes=512,
            preview_bytes=513,
        )
